# Sections 6.2-6.4 and Supplement S2.8: the worked example, one simulated
# experiment of 80 participants generated by carried associability (seed 8123,
# chosen before the result was seen). Computes the B-D difference, the
# candidates' fits and their held-out comparison (Figures 7 and S2), the profile
# likelihood of g_alpha (Figure S1b) and the mimicry fits to the generating
# probabilities (Figure S1a), and writes the table of fitted parameters of
# Supplement S2.8 (supplement_fitted_parameters.tex).
#   Rscript analysis/section6_worked_example.R

if (!file.exists("R/inference.R")) stop("Run this script from the repository root.")
source("R/inference.R")
source("R/figure_style.R")  # paper_number()

n_participants <- 80
example_seed <- 8123L
starts <- 48L
output <- "results/section6"
scenarios <- inference_scenarios()

# Sections 6.2 and 6.3: the experiment, the three candidates fitted to all 80
# participants (Figures 7b and S2), their held-out comparison (Figure 7c) and
# the B-D difference with its interval (Figure 7a).
example <- inference_generate(n_participants, scenarios$associability$par, TRUE,
                              seed = example_seed)
example$fits <- list()
for (model in c("fixed", "reset", "carry")) {
  # The carryover fit also starts from the reset solution (Supplement S2.7).
  nested <- if (model == "carry") example$fits$reset$par else NULL
  example$fits[[model]] <- inference_fit(example$observed, inference_spec(model),
                                         starts = starts, extra_start = nested)
}
example$comparison <- inference_compare(example$observed, starts = starts)
example$effect <- inference_effect(example$observed)
saveRDS(example, file.path(output, "worked_example.rds"))
# Columns B1-B10 hold the responses on B's ten pear trials and D1-D10 those on
# D's; allocation is the counterbalancing group, a_s of Supplement S2.2.
responses <- example$observed$y
colnames(responses) <- c(paste0("B", 1:10), paste0("D", 1:10))
write.csv(data.frame(participant = seq_len(n_participants),
                     allocation = example$observed$allocation, responses),
          file.path(output, "worked_example_responses.csv"), row.names = FALSE)

# Section 6.4 and Supplement S2.8: the profile likelihood of g_alpha, fixed at
# 0, .1, ..., 1 with the other parameters of the carryover candidate
# re-estimated at each value.
profile <- lapply(seq(0, 1, by = .1), function(g_alpha) {
  spec <- inference_spec("carry")
  spec$free <- setdiff(spec$free, "g_alpha")
  criterion <- function(par) {
    par["g_alpha"] <- g_alpha
    -sum(inference_loglik_cpp(par, TRUE, example$observed$y, example$observed$allocation))
  }
  fit <- inference_fit(example$observed, spec, starts = starts, criterion = criterion)
  data.frame(g_alpha = g_alpha, nll = fit$nll, converged = fit$converged,
             eta = fit$par["eta"], g_value = fit$par["g_value"],
             mu = fit$par["mu"], slope = exp(fit$par["log_slope"]))
})
profile <- do.call(rbind, profile)
write.csv(profile, file.path(output, "carryover_profile.csv"), row.names = FALSE)

# Section 6.4 and Supplement S2.8: each candidate fitted directly to the
# generating probabilities of carried associability and of carried learned
# value, without learning-rate types (tau = 0) and with both counterbalancing
# groups. The criterion is the expected KL divergence of one participant's
# analyzed responses, averaged over the two groups, which are rows 1 and 3 of
# the probability matrix when tau = 0.
divergence <- function(p, p_fit) {
  p_fit <- pmax(1e-12, pmin(1 - 1e-12, p_fit))
  p * log(p / p_fit) + (1 - p) * log((1 - p) / (1 - p_fit))
}
# inference_fit() takes a set of responses, but a criterion replaces its
# likelihood; this four-participant template only marks the responses kept
# from pear trials 8-10 (late), 1-6 (early) or all ten (full).
template <- list(y = matrix(0L, 4L, 20L), allocation = c(-1L, -1L, 1L, 1L), n_train = 10L)
landscape <- list()
for (scenario in c("associability", "value")) {
  generator <- scenarios[[scenario]]
  generator$par["spread"] <- 0
  generating <- inference_prob_cpp(generator$par, generator$adaptive)[c(1L, 3L), ]
  for (view in c("late", "early", "full")) {
    kept <- which(!is.na(inference_view(template, view)$y[1, ]))
    for (model in c("fixed", "reset", "carry")) {
      spec <- inference_spec(model)
      spec$free <- setdiff(spec$free, "spread")
      criterion <- function(par) {
        fitted <- inference_prob_cpp(par, spec$adaptive)[c(1L, 3L), kept, drop = FALSE]
        sum(divergence(generating[, kept, drop = FALSE], fitted)) / 2
      }
      fit <- inference_fit(template, spec, starts = starts, criterion = criterion)
      # The divergence before refitting: the generating values, with eta and
      # g_alpha set to 0 for the fixed-rate candidate and g_alpha set to 0 for
      # the reset candidate.
      reference <- generator$par
      if (model == "fixed") reference[c("eta", "g_alpha")] <- 0
      if (model == "reset") reference["g_alpha"] <- 0
      # fit$nll is the divergence of the selected search, the best converged
      # one within 1e-5 of the smallest found (Supplement S2.7), so it can lie
      # slightly above the smallest. Below 1e-8 it counts as reaching the lower
      # bound of zero.
      landscape[[length(landscape) + 1L]] <- data.frame(
        scenario = scenario, view = view, model = model,
        reference_kl = criterion(reference), fitted_kl = fit$nll,
        optimizer_converged = fit$converged, kl_lower_bound_reached = fit$nll < 1e-8,
        as.list(fit$par))
    }
  }
}
landscape <- do.call(rbind, landscape)
write.csv(landscape, file.path(output, "landscape.csv"), row.names = FALSE)

mimicry <- function(view, model) {
  landscape[landscape$scenario == "associability" & landscape$view == view &
              landscape$model == model, ]
}
# Section 6.4: the reset candidate's divergence over all ten pear trials,
# response by response, and the share of it in the first two pear trials with
# each light.
generator <- scenarios$associability
generator$par["spread"] <- 0
reset_par <- unlist(mimicry("full", "reset")[inference_names])
reset_by_response <- colSums(divergence(inference_prob_cpp(generator$par, TRUE)[c(1L, 3L), ],
                                        inference_prob_cpp(reset_par, TRUE)[c(1L, 3L), ])) / 2
first_two_share <- sum(reset_by_response[c(1, 2, 11, 12)]) / sum(reset_by_response)
# Section 6.4: the generating D-B difference in the probability of a yes
# response on pear trials 8-10, averaged over the two counterbalancing groups.
generating <- inference_prob_cpp(generator$par, TRUE)[c(1L, 3L), ]
late_gap <- colMeans(generating[, 18:20] - generating[, 8:10])
write.csv(data.frame(reset_first_two_share = first_two_share,
                     late_gap_min = min(late_gap), late_gap_max = max(late_gap)),
          file.path(output, "mimicry_summary.csv"), row.names = FALSE)

# Supplement S2.8: the table of the parameters of the three candidates fitted to
# all 80 participants, beside the generating values. mu, tau and d are on the
# logit(2r) scale of Equation S2, and the slope is shown as gamma rather than
# log gamma. A dash marks a parameter that the candidate does not estimate, and
# an asterisk an estimate on a bound (Supplement S2.5).
symbols <- c(mu = "$\\mu$", spread = "$\\tau$", cue = "$d$", intercept = "$b$",
             log_slope = "$\\gamma$", g_value = "$g_V$", eta = "$\\eta$",
             g_alpha = "$g_\\alpha$")
format_value <- function(name, x) {
  if (name == "log_slope") x <- exp(x)
  if (name %in% c("g_value", "g_alpha")) return(paper_number(x, 2))
  if (name == "eta") return(paper_number(x, 3))
  sub("^-", "$-$", sprintf("%.2f", x))
}
cell <- function(model, name) {
  fit <- example$fits[[model]]
  if (!(name %in% fit$spec$free)) return("--")
  on_bound <- name %in% strsplit(fit$boundary, ";")[[1]]
  paste0(format_value(name, fit$par[[name]]), if (on_bound) "*")
}
fitted_rows <- vapply(names(symbols), function(name) {
  paste(symbols[[name]], format_value(name, example$truth$par[[name]]), cell("fixed", name),
        cell("reset", name), cell("carry", name), sep = " & ")
}, "", USE.NAMES = FALSE)
writeLines(c("\\begin{center}", "\\small", "\\begin{tabular}{@{}lrrrr@{}}", "\\toprule",
             "Parameter & Generating & Fixed-rate & Reset & Carryover \\\\", "\\midrule",
             paste(fitted_rows, "\\\\"), "\\bottomrule", "\\end{tabular}", "\\end{center}"),
           file.path(output, "supplement_fitted_parameters.tex"))
# The fixed-rate candidate's probabilities of a yes response on the first pear
# trial with B (column 1) and with D (column 11), in each counterbalancing
# group and learning-rate type.
fixed_first <- inference_prob_cpp(example$fits$fixed$par, FALSE)[, c(1, 11)]

contrasts <- example$comparison$carry_contrasts
cat(sprintf("Mean B-D difference %s, 95%% interval %s to %s\n",
            paper_number(example$effect[["estimate"]], 3),
            paper_number(example$effect[["lower"]], 3),
            paper_number(example$effect[["upper"]], 3)))
cat(sprintf("Carryover of learned value g_V: fixed-rate %s, reset %s\n",
            paper_number(example$fits$fixed$par[["g_value"]], 2),
            paper_number(example$fits$reset$par[["g_value"]], 2)))
cat(sprintf("Held-out log score, carryover minus fixed-rate %.1f (SE %.1f),",
            contrasts["fixed", "difference"], contrasts["fixed", "se"]),
    sprintf("minus reset %.1f (SE %.1f)\n", contrasts["reset", "difference"],
            contrasts["reset", "se"]))
cat(sprintf("Profile likelihood of g_alpha highest at %g\n",
            profile$g_alpha[which.min(profile$nll)]))
cat(sprintf("KL divergence per participant, fixed-rate %.3f (%.3f before refitting), reset %.3f;",
            mimicry("full", "fixed")$fitted_kl, mimicry("full", "fixed")$reference_kl,
            mimicry("full", "reset")$fitted_kl),
    sprintf("reset on pear trials 8-10 %.4f\n", mimicry("late", "reset")$fitted_kl))
cat(sprintf("Reset, all ten pear trials: %s of its divergence lies in the first two",
            paper_number(first_two_share, 2)), "pear trials with each light\n")
cat(sprintf("Generating D-B difference on pear trials 8-10: %s to %s\n",
            paper_number(min(late_gap), 3), paper_number(max(late_gap), 3)))
cat("Saved results/section6/worked_example.rds, worked_example_responses.csv,",
    "carryover_profile.csv, landscape.csv, mimicry_summary.csv and",
    "supplement_fitted_parameters.tex\n")

# The table of fitted parameters as Supplement S2.8 prints it
printed_fitted <- c(
  "$\\mu$ & $-$0.85 & $-$2.00 & $-$1.97 & $-$0.90",
  "$\\tau$ & 0.35 & 0.21 & 0.24 & 0.38",
  "$d$ & 0.20 & 0.10 & 0.12 & 0.16",
  "$b$ & $-$4.00 & $-$6.98 & $-$5.22 & $-$4.06",
  "$\\gamma$ & 8.00 & 16.00* & 11.14 & 8.34",
  "$g_V$ & .00 & .70 & .50 & .00*",
  "$\\eta$ & .050 & -- & .200* & .045",
  "$g_\\alpha$ & .80 & -- & -- & 1.00*"
)

# Values reported in the paper
stopifnot(
  sprintf("%.3f", example$effect[c("estimate", "lower", "upper")]) ==
    c("0.212", "0.174", "0.251"),                                      # Section 6.2
  sprintf("%.2f", example$fits$fixed$par[["g_value"]]) == "0.70",      # Section 6.3
  sprintf("%.2f", example$fits$reset$par[["g_value"]]) == "0.50",
  sprintf("%.1f", contrasts[, "difference"]) == c("20.5", "21.1"),     # Section 6.3, Figure 7c
  sprintf("%.1f", contrasts[, "se"]) == c("5.9", "5.1"),
  example$comparison$decision == "carry",
  profile$g_alpha[which.min(profile$nll)] == 1,                        # Section 6.4
  max(profile$nll[profile$g_alpha >= .5]) - min(profile$nll) < .5,     # Section 6.4
  all(diff(profile$eta) < 1e-6),       # Section 6.4: less carryover, a faster estimated eta
  sprintf("%.3f", mimicry("full", "fixed")$reference_kl) == "1.417",   # Supplement S2.8
  # Section 6.4 (divided by the number of responses) and Supplement S2.8
  sprintf("%.3f", mimicry("full", "fixed")$fitted_kl) == "0.119",
  sprintf("%.3f", mimicry("full", "reset")$fitted_kl) == "0.143",
  sprintf("%.4f", mimicry("late", "fixed")$fitted_kl) == "0.0019",
  sprintf("%.4f", mimicry("late", "reset")$fitted_kl) == "0.0015",
  # Section 6.4: on pear trials 8-10 both alternatives carry over all of the
  # learned value for the apple
  c(mimicry("late", "fixed")$g_value, mimicry("late", "reset")$g_value) > .999,
  round(100 * first_two_share) == 41,                                  # Section 6.4
  sprintf("%.2f", range(late_gap)) == c("0.23", "0.33"),               # Section 6.4
  # Supplement S2.8: the table of fitted parameters, with the bounds it marks.
  # All three fits converged, and the fixed-rate candidate's slope is at its
  # upper bound of 16.
  identical(fitted_rows, printed_fitted),
  vapply(example$fits, `[[`, logical(1), "converged"),
  example$fits$fixed$boundary == "log_slope", example$fits$reset$boundary == "eta",
  example$fits$carry$boundary == "g_value;g_alpha",
  abs(exp(example$fits$fixed$par[["log_slope"]]) - 16) < 1e-6,
  # Supplement S2.8 and Section 6.3: the fixed-rate candidate's probabilities of
  # a yes response on the first pear trial are below .1 for both lights and
  # differ by about .05
  fixed_first < .1,
  sprintf("%.2f", mean(fixed_first[, 2]) - mean(fixed_first[, 1])) == "0.05"
)
